use glam::{DVec3,DMat4};use ingetrazo_core::{scene::{Scene,SelectionItem},math::Ray,groups::Group};use ingetrazo_tools::base::{ToolContext,ToolType};use ingetrazo_gui::IngeTrazoApp;use serde_json::{json,Value};
fn snapshot(app:&IngeTrazoApp,text:&str)->Value{let s=&app.scene;let mut faces=s.mesh.faces.iter().map(|f|{let x=f.vertices.iter().map(|&v|s.mesh.vertices[v].position.x).fold(f64::INFINITY,f64::min);json!([x,f.holes.len(),f.attrs["vendor"],f.attrs["texture"]["uvw"][3]])}).collect::<Vec<_>>();faces.sort_by(|a,b|a[0].as_f64().unwrap().total_cmp(&b[0].as_f64().unwrap()));let mut curves=std::collections::BTreeMap::new();for e in &s.mesh.edges{if let Some(id)=e.curve_id{*curves.entry(id).or_insert(0)+=1;}}let mut roots=s.groups.iter().map(|g|g.transform.transform_point3(DVec3::ZERO).x).collect::<Vec<_>>();roots.sort_by(f64::total_cmp);let mut segments=s.mesh.edges.iter().map(|e|{let a=s.mesh.vertices[e.v0].position.to_array();let b=s.mesh.vertices[e.v1].position.to_array();if a<b{[a,b]}else{[b,a]}}).collect::<Vec<_>>();segments.sort_by(|a,b|a.partial_cmp(b).unwrap());json!({"edge_segments":segments,"text":text,"faces":faces,"edges":s.mesh.edges.len(),"curve_edges":curves.values().sum::<usize>(),"curve_groups":curves.len(),"source_curve_retained":curves.contains_key(&91),"pair_links":curves.values().all(|&n|n==2),"groups_x":roots,"undo":app.undo_stack.len()})}
fn main(){let mut s=Scene::new();let outer=[DVec3::ZERO,DVec3::X*4.,DVec3::new(4.,4.,0.),DVec3::Y*4.].map(|p|s.mesh.add_vertex(p));let hole=[DVec3::new(1.,1.,0.),DVec3::new(1.,3.,0.),DVec3::new(3.,3.,0.),DVec3::new(3.,1.,0.)].map(|p|s.mesh.add_vertex(p));let f=s.mesh.add_face(outer.to_vec(),vec![hole.to_vec()]).unwrap();s.mesh.faces[f].attrs.insert("vendor".into(),json!(71));s.mesh.faces[f].attrs.insert("texture".into(),json!({"uvw":[1.,0.,0.,2.,0.,1.,0.,3.],"path":"tile.png"}));let a=s.mesh.add_vertex(DVec3::new(0.,10.,0.));let b=s.mesh.add_vertex(DVec3::new(1.,10.,0.));let c=s.mesh.add_vertex(DVec3::new(1.,11.,0.));let e=s.mesh.add_edge(a,b).unwrap();let h=s.mesh.add_edge(b,c).unwrap();for id in [e,h]{s.mesh.edges[id].soft=true;s.mesh.edges[id].curve_id=Some(91);}let mut g=Group::new("private");g.transform=DMat4::from_translation(DVec3::new(2.,3.,0.));let a=g.mesh.add_vertex(DVec3::ZERO);let b=g.mesh.add_vertex(DVec3::X);g.mesh.add_edge(a,b);s.groups.push(g);let mut app=IngeTrazoApp::new();app.scene=s;app.set_tool(ToolType::Move);for item in [SelectionItem::Face(f),SelectionItem::Edge(e),SelectionItem::Edge(h),SelectionItem::Group(0)]{app.scene.select(item);}let mut first=ToolContext::new(DVec3::ZERO,Ray::new(DVec3::Z*10.,-DVec3::Z));first.ctrl_held=true;app.dispatch_tool_click(&first);app.dispatch_tool_vcb("18;0;0").unwrap();let mut states=vec![];for text in ["3x","/3","2x"]{app.dispatch_tool_vcb(text).unwrap();states.push(snapshot(&app,text));}app.undo();let undo=snapshot(&app,"undo");app.redo();let redo=snapshot(&app,"redo");std::fs::write(std::env::args().nth(1).unwrap(),serde_json::to_vec_pretty(&json!({"states":states,"undo":undo,"redo":redo})).unwrap()).unwrap();}
